1	import {WebSocket} from 'ws';
2	import type {SessionEntry} from '../../types/session.js';
3	import type {ChatSession} from '../../types/session.js';
4	import {ErrorCodes} from '../../types/messages.js';
5	import type {OutgoingMessage} from '../../types/messages.js';
6	import {ThinkingTagParser, ParsedSegment} from '../../infrastructure/parsers/thinkingTagParser.js';
7	import {validateMessage} from './validation.js';
8	import type {ValidationResult} from './validation.js';
9	import {PerSessionLock} from '../../shared/perSessionLock.js';
10	import type {ChatOrchestrator} from '../../orchestration/chatOrchestrator.js';
11	import type {SessionStore} from '../../types/sessionStore.js';
12	import {AIError} from '../../types/ai.js';
13	import type {MessageChunk} from '../../types/ai.js';
14	import {
15	  createUserEntry,
16	  createAssistantEntry,
17	  createThinkingEntry,
18	  createToolEntry,
19	} from '../../orchestration/entryFactories.js';
20	import {appendEntry, appendDelta, commitEntry, markTruncated} from '../../orchestration/entryMutations.js';
21	import {sendJson, sendUpsert, sendDelta, sendCommit, sendSkip, sendError, sendStreamEnd} from './sender.js';
22	import {log} from '../../shared/logger.js';
23	
24	interface StreamState {
25	  thinkingIndex: number | null;
26	  assistantIndex: number | null;
27	  suppressOutput: boolean;
28	  sentAssistantIndices: number[];
29	}
30	
31	type StateIndexKey = 'thinkingIndex' | 'assistantIndex';
32	type EntryFactory = typeof createThinkingEntry | typeof createAssistantEntry;
33	export function createMessageHandler(orchestrator: ChatOrchestrator, sessionStore?: SessionStore) {
34	  // Keyed by session, not socket: a resumed session can be open on more than one (specs/hal-engine-architecture/spec.md).
35	  const lock = new PerSessionLock();
36	  return function handleMessage(
37	    ws: WebSocket,
38	    session: ChatSession,
39	    rawMessage: unknown,
40	    signal?: AbortSignal
41	  ): Promise<void> {
42	    const validation = validateMessage(rawMessage);
43	    // Queued with no await before it, so a session's user_messages, a failed one too, are answered in arrival order.
44	    if (isUserMessageFrame(rawMessage)) {
45	      return lock.run(session.sessionId, () => answerInTurn(ws, session, orchestrator, validation, signal));
46	    }
47	    // An async action runs up to its first await at once, so a ping is answered now and a throw stays a rejection.
48	    return wsErrorHandler(ws, async () => answerFrame(ws, validation, sessionStore));
49	  };
50	}
51	
52	// The whole answer, an error and the stream_end included, goes out inside the lock: an error frame names no message.
53	async function answerInTurn(
54	  ws: WebSocket,
55	  session: ChatSession,
56	  orchestrator: ChatOrchestrator,
57	  validation: ValidationResult,
58	  signal: AbortSignal | undefined
59	): Promise<void> {
60	  // Its socket closed while it waited: nobody is left to read the answer, and a session's last close took its credentials.
61	  if (signal?.aborted || ws.readyState === WebSocket.CLOSING || ws.readyState === WebSocket.CLOSED) {
62	    log.info('message', 'queued message dropped: its socket closed', {sessionId: session.sessionId});
63	    return;
64	  }
65	  const startedAt = Date.now();
66	  try {
67	    await wsErrorHandler(ws, () => answerUserMessage(ws, session, orchestrator, validation, signal));
68	  } finally {
69	    endTurn(ws, session, signal, startedAt);
70	  }
71	}
72	
73	// A turn whose socket closed is abandoned rather than ended: nobody is left to read a terminal frame.
74	function endTurn(ws: WebSocket, session: ChatSession, signal: AbortSignal | undefined, startedAt: number): void {
75	  if (signal?.aborted) {
76	    log.info('message', 'turn abandoned: its socket closed', {
77	      sessionId: session.sessionId,
78	      elapsedMs: Date.now() - startedAt,
79	    });
80	    return;
81	  }
82	  sendStreamEnd(ws);
83	}
84	
85	async function answerUserMessage(
86	  ws: WebSocket,
87	  session: ChatSession,
88	  orchestrator: ChatOrchestrator,
89	  validation: ValidationResult,
90	  signal: AbortSignal | undefined
91	): Promise<void> {
92	  const message = validation.valid ? validation.data : undefined;
93	  if (message?.type === 'user_message') return handleUserMessage(ws, session, orchestrator, message.content, signal);
94	  await answerFrame(ws, validation);
95	}
96	
97	async function answerFrame(ws: WebSocket, validation: ValidationResult, sessionStore?: SessionStore): Promise<void> {
98	  if (!validation.valid) {
99	    log.warn('message', 'validation failed', {error: validation.error});
100	    sendError(ws, ErrorCodes.INVALID_MESSAGE, validation.error);
101	    return;
102	  }
103	
104	  const message = validation.data;
105	  if (message.type === 'ping') handlePing(ws, message.timestamp);
106	  if (message.type === 'list_sessions') await handleListSessions(ws, message, sessionStore);
107	}
108	
109	async function handleListSessions(
110	  ws: WebSocket,
111	  message: {type: 'list_sessions'; limit?: number; before?: {updatedAt: string | number; sessionId: string}},
112	  sessionStore?: SessionStore
113	): Promise<void> {
114	  if (!sessionStore?.listFor) {
115	    sendJson(ws, {type: 'session_list', sessions: []});
116	    return;
117	  }
118	  try {
119	    const sessions = await sessionStore.listFor((ws as WebSocket & {userId: string | number}).userId, {
120	      limit: message.limit,
121	      before: message.before,
122	    });
123	    sendJson(ws, {
124	      type: 'session_list',
125	      sessions: sessions.map(({createdAt, updatedAt, ...summary}) => ({
126	        ...summary,
127	        createdAt: createdAt.toISOString(),
128	        updatedAt: updatedAt.toISOString(),
129	      })),
130	    });
131	  } catch (error) {
132	    log.error('ws', 'conversation list failed', {
133	      sessionId: (ws as WebSocket & {sessionId?: string}).sessionId,
134	      userId: (ws as WebSocket & {userId?: string | number}).userId,
135	      error: error instanceof Error ? error.message : 'Unknown error',
136	    });
137	    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to process message');
138	  }
139	}
140	
141	// Read from the raw frame, so a user_message that fails validation still gets its stream_end.
142	function isUserMessageFrame(rawMessage: unknown): boolean {
143	  return typeof rawMessage === 'object' && rawMessage !== null && Reflect.get(rawMessage, 'type') === 'user_message';
144	}
145	
146	async function wsErrorHandler(ws: WebSocket, action: () => Promise<void>): Promise<void> {
147	  try {
148	    await action();
149	  } catch (error) {
150	    const message = error instanceof Error ? error.message : 'Unknown error';
151	    const code = error instanceof AIError ? error.code : 'UNKNOWN';
152	    log.error('message', 'handling error', {error: message, code});
153	    if (error instanceof AIError && error.code === 'RATE_LIMITED') {
154	      sendError(ws, ErrorCodes.RATE_LIMITED, 'AI service is busy, please try again');
155	      return;
156	    }
157	    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to process message');
158	  }
159	}
160	
161	async function handleUserMessage(
162	  ws: WebSocket,
163	  session: ChatSession,
164	  orchestrator: ChatOrchestrator,
165	  content: string,
166	  signal: AbortSignal | undefined
167	): Promise<void> {
168	  log.info('message', 'user message received', {sessionId: session.sessionId, contentLength: content.length});
169	
170	  const userEntry = createUserEntry(content);
171	  const userIndex = appendEntry(session, userEntry);
172	  sendUpsert(ws, userIndex, userEntry);
173	
174	  const parser = new ThinkingTagParser();
175	  const state: StreamState = {
176	    thinkingIndex: null,
177	    assistantIndex: null,
178	    suppressOutput: false,
179	    sentAssistantIndices: [],
180	  };
181	
182	  let textChunkCount = 0;
183	
184	  try {
185	    for await (const chunk of orchestrator.processMessageStream(session, {signal})) {
186	      // Its socket closed: breaking returns the run's generator, so the run stops and its own teardown still runs.
187	      if (signal?.aborted) break;
188	      textChunkCount = logChunk(chunk, textChunkCount);
189	      processChunk(ws, session, state, parser, chunk);
190	    }
191	  } finally {
192	    // Anything still open here was cut short: a stop has already flushed the parser and committed every entry it opened.
193	    flushHeldText(ws, session, state, parser);
194	    closeCutOff(ws, session, state, 'thinkingIndex');
195	    closeCutOff(ws, session, state, 'assistantIndex');
196	  }
197	
198	  if (textChunkCount > 0) {
199	    log.debug('stream', `received ${textChunkCount} text chunks`);
200	  }
201	  log.info('stream', 'stream completed', {suppressed: state.suppressOutput, entries: session.entries.length});
202	}
203	
204	// Diagnostics only: counts a run of text chunks so it is logged once, not per token.
205	function logChunk(chunk: MessageChunk, textChunkCount: number): number {
206	  if (chunk.type === 'text') return textChunkCount + 1;
207	
208	  if (textChunkCount > 0) {
209	    log.debug('stream', `received ${textChunkCount} text chunks`);
210	  }
211	
212	  if (chunk.type === 'tool_result') {
213	    log.debug('stream', 'tool_result chunk', {
214	      messageCount: chunk.clientMessages.length,
215	      types: chunk.clientMessages.map(m => m.type),
216	    });
217	    return 0;
218	  }
219	
220	  log.debug('stream', 'chunk', {type: chunk.type});
221	  return 0;
222	}
223	
224	function processChunk(
225	  ws: WebSocket,
226	  session: ChatSession,
227	  state: StreamState,
228	  parser: ThinkingTagParser,
229	  chunk: MessageChunk
230	): void {
231	  if (chunk.type === 'text') return processTextChunk(ws, session, state, parser, chunk.text);
232	  if (chunk.type === 'tool_use') return processToolUseChunk(ws, session, chunk.toolCall);
233	  if (chunk.type === 'tool_result') return processToolResultChunk(ws, chunk.clientMessages);
234	  if (chunk.type === 'suppress_output') return processSuppressChunk(ws, session, state);
235	  if (chunk.type === 'stop') return processStopChunk(ws, session, state, parser);
236	}
237	
238	function processTextChunk(
239	  ws: WebSocket,
240	  session: ChatSession,
241	  state: StreamState,
242	  parser: ThinkingTagParser,
243	  text: string
244	): void {
245	  const segments = parser.push(text);
246	  for (const segment of segments) {
247	    handleTextSegment(ws, session, state, segment);
248	  }
249	}
250	
251	function handleTextSegment(ws: WebSocket, session: ChatSession, state: StreamState, segment: ParsedSegment): void {
252	  if (segment.type === 'thinking') {
253	    streamSegment(ws, session, state, 'thinkingIndex', createThinkingEntry, segment.content);
254	    return;
255	  }
256	  commitAndClear(ws, session, state, 'thinkingIndex');
257	  streamSegment(ws, session, state, 'assistantIndex', createAssistantEntry, segment.content);
258	}
259	
260	function streamSegment(
261	  ws: WebSocket,
262	  session: ChatSession,
263	  state: StreamState,
264	  key: StateIndexKey,
265	  createEntry: EntryFactory,
266	  content: string
267	): void {
268	  const isNew = initSegment(session, state, key, createEntry);
269	  if (isNew && state.suppressOutput) skipSuppressed(ws, session, state[key]!);
270	  if (isNew && !state.suppressOutput) sendUpsert(ws, state[key]!, session.entries[state[key]!]);
271	  appendDelta(session, state[key]!, content);
272	  if (!state.suppressOutput) sendDelta(ws, state[key]!, content);
273	}
274	
275	// Stored as suppressed, so a replay on resume shows the client what it saw live and not the text a tool hid.
276	function skipSuppressed(ws: WebSocket, session: ChatSession, index: number): void {
277	  markSuppressed(session, index);
278	  sendSkip(ws, index);
279	}
280	
281	function markSuppressed(session: ChatSession, index: number): void {
282	  const entry = session.entries[index];
283	  if (entry.role === 'assistant' || entry.role === 'thinking') entry.suppressed = true;
284	}
285	
286	function initSegment(session: ChatSession, state: StreamState, key: StateIndexKey, createEntry: EntryFactory): boolean {
287	  if (state[key] !== null) return false;
288	  state[key] = appendEntry(session, createEntry());
289	  return true;
290	}
291	
292	function commitAndClear(ws: WebSocket, session: ChatSession, state: StreamState, key: StateIndexKey): void {
293	  const index = state[key];
294	  if (index === null) return;
295	
296	  commitEntry(session, index);
297	  state[key] = null;
298	
299	  // Only what the client received can be retracted, and only assistant entries.
300	  if (state.suppressOutput) return;
301	
302	  sendCommit(ws, index);
303	  if (key === 'assistantIndex') state.sentAssistantIndices.push(index);
304	}
305	
306	function processToolUseChunk(
307	  ws: WebSocket,
308	  session: ChatSession,
309	  toolCall: {name: string; input: Record<string, unknown>}
310	): void {
311	  const toolEntry = createToolEntry(toolCall.name, toolCall.input);
312	  const toolIndex = appendEntry(session, toolEntry);
313	  sendUpsert(ws, toolIndex, toolEntry);
314	}
315	
316	function processToolResultChunk(ws: WebSocket, clientMessages: OutgoingMessage[]): void {
317	  for (const msg of clientMessages) {
318	    log.debug('stream', 'forwarding client message to frontend', {
319	      type: msg.type,
320	      index: 'index' in msg ? msg.index : undefined,
321	    });
322	    sendJson(ws, msg);
323	  }
324	}
325	
326	// Retracts what the client saw: every assistant entry sent so far is re-sent blank.
327	function processSuppressChunk(ws: WebSocket, session: ChatSession, state: StreamState): void {
328	  // Closed as streamed so far: an open answer is then retracted like a sent one, and what follows opens new entries.
329	  commitOpenEntries(ws, session, state);
330	  log.debug('stream', 'suppression activated', {blankingEntries: state.sentAssistantIndices});
331	
332	  for (const idx of state.sentAssistantIndices) {
333	    sendUpsert(ws, idx, {...session.entries[idx], content: ''} as SessionEntry);
334	    markSuppressed(session, idx);
335	  }
336	
337	  state.sentAssistantIndices = [];
338	  state.suppressOutput = true;
339	}
340	
341	function processStopChunk(ws: WebSocket, session: ChatSession, state: StreamState, parser: ThinkingTagParser): void {
342	  flushHeldText(ws, session, state, parser);
343	  commitOpenEntries(ws, session, state);
344	}
345	
346	// The parser holds back a tail that might open a tag; without this the tail of a cut-off answer would be lost.
347	function flushHeldText(ws: WebSocket, session: ChatSession, state: StreamState, parser: ThinkingTagParser): void {
348	  for (const segment of parser.flush()) {
349	    handleTextSegment(ws, session, state, segment);
350	  }
351	}
352	
353	// The flag lives on the stored entry even when suppressed; only a visible entry is re-sent, which is how a live client learns it.
354	function closeCutOff(ws: WebSocket, session: ChatSession, state: StreamState, key: StateIndexKey): void {
355	  const index = state[key];
356	  if (index === null) return;
357	  markTruncated(session, index);
358	  if (!state.suppressOutput) sendUpsert(ws, index, session.entries[index]);
359	  commitAndClear(ws, session, state, key);
360	}
361	
362	function commitOpenEntries(ws: WebSocket, session: ChatSession, state: StreamState): void {
363	  commitAndClear(ws, session, state, 'thinkingIndex');
364	  commitAndClear(ws, session, state, 'assistantIndex');
365	}
366	
367	function handlePing(ws: WebSocket, timestamp: number): void {
368	  ws.send(JSON.stringify({type: 'pong', timestamp}));
369	}
